### Step 1: API Authentication بـ JWT

```python
import jwt
from datetime import datetime, timedelta

JWT_SECRET = os.environ['JWT_SECRET']  # مش hardcoded!
JWT_ALGORITHM = 'HS256'
JWT_EXPIRY = timedelta(minutes=30)  # short expiry للـ SCADA!

def generate_token(user):
    payload = {
        'sub': user.id,
        'role': user.role,
        'zones': user.zones,
        'exp': datetime.utcnow() + JWT_EXPIRY,
        'iat': datetime.utcnow(),
        'jti': secrets.token_hex(16)  # unique token ID
    }
    return jwt.encode(payload, JWT_SECRET, algorithm=JWT_ALGORITHM)

@app.before_request
def verify_token():
    if request.endpoint == 'login':
        return  # skip for login
    token = request.headers.get('Authorization', '').replace('Bearer ', '')
    try:
        payload = jwt.decode(token, JWT_SECRET, algorithms=[JWT_ALGORITHM])
        g.user = payload
    except jwt.ExpiredSignatureError:
        abort(401, "Token expired")
    except jwt.InvalidTokenError:
        abort(401, "Invalid token")
```

### Step 2: Level-Based Authorization

```python
def require_api_level(level):
    def decorator(f):
        @wraps(f)
        def decorated(*args, **kwargs):
            user_level = API_LEVELS.get(g.user['role'], 0)
            if user_level < level:
                audit_logger.critical(
                    f"API ACCESS DENIED: user={g.user['sub']} "
                    f"endpoint={f.__name__} required_level={level} "
                    f"user_level={user_level}"
                )
                abort(403)
            return f(*args, **kwargs)
        return decorated
    return decorator

# Level 4 = Critical (valve commands)
@app.route('/api/valve/<valve_id>/<action>', methods=['POST'])
@require_api_level(4)
def control_valve(valve_id, action):
    # Re-authentication for critical operations
    password = request.json.get('confirm_password')
    if not verify_password(g.user['sub'], password):
        abort(401, "Re-authentication required")

    # Safety interlock check
    if not safety_interlock_check(valve_id, action):
        abort(409, "Safety interlock prevents this action")

    # Dual confirmation
    if not request.json.get('confirmed_by_second_person'):
        return {"status": "dual_confirmation_required"}

    return execute_valve_command(valve_id, action)
```

